  启用连接资格迹衰减: "Enable edge eligibility decay",
  孤立节点未触达期限: "Isolated node untouched period",
  实施计划与待议机制: "Implementation plans and open mechanisms",
  "按旧候选规则限制共同激活候选，包括出生与已有边更新。0 关闭额外门槛，不限制独立传播巩固。":
    "Apply the old candidate gate to coactivation, including birth and existing-edge updates. Zero disables this extra gate; independent traversal consolidation is unaffected.",
  "损失 Δt/τ × (1−节点稳定度)，是线性损失尺度；关闭请使用支持度衰减开关。":
    "Loss is Δt/τ × (1−node stability), a linear loss scale. Use the support-loss switch to disable it.",
  "控制节点触达痕迹，旧每 0.1 秒保留 0.82；与连接资格迹分别配置。":
    "Node contact trace retains 0.82 per 0.1 seconds under the old defaults. Configured separately from edge eligibility.",
  无激活死亡宽限期: "Quiescence death grace period",
  "旧每 0.1 秒保留 0.78，换算为独立时间常数；资格迹影响稳定度损失。":
    "The old retention of 0.78 per 0.1 seconds is converted to a separate time constant. Eligibility affects stability loss.",
  "每周期损失 Δt/τ × (1−资格迹)，是线性损失尺度，不是指数衰减；节点稳定度按旧机制在触达时增长。":
    "Per-cycle loss is Δt/τ × (1−eligibility), a linear scale. Node stability grows on contact under the old rule.",
  "直接刺激在目标抑制和饱和之前按触达量收费；储备不足降低可负担的触达量。":
    "Direct input is charged before target inhibition and saturation. Insufficient reserves reduce affordable contact.",
  节点支持度损失时间尺度: "Node support loss timescale",
  节点触达痕迹时间常数: "Node contact trace time constant",
  "软饱和曲线 cap × tanh(q/cap) 的尺度，默认 1；按传播节律执行，非每次数值小步硬封顶。":
    "Scale of cap × tanh(q/cap), default 1. Applied at the propagation rhythm, without hard clipping on every solver step.",
  连接稳定度损失时间尺度: "Edge stability loss timescale",
  连接资格迹衰减时间常数: "Edge eligibility decay time constant",
  "首次激活后，全部节点连续无激活达到此时长才死亡；默认 1 模拟秒。0 表示同一时刻事件处理完后立即判定，不代表关闭死亡。":
    "After first activation, death requires continuous quiescence for this period; default 1 simulation second. Zero checks immediately after all same-time events, rather than disabling death.",
  "默认 100000（0.1 模拟秒）。传播和离散非线性操作的模型节律，独立于数值步长与显示刷新。修改后从生效时刻开始新周期。":
    "Default 100000 μs (0.1 simulation seconds). Rhythm of propagation and discrete nonlinear operations, independent of solver and display rates. Changing it starts a new period at the effective time.",
  "默认 80 模拟秒。须同时孤立、无激活、支持不足且超过此未触达期限才修剪；0 仅撤去等待期限。":
    "Default 80 simulation seconds. Pruning requires isolation, zero activation, insufficient support and an untouched interval longer than this period. Zero removes only the waiting period.",
  "默认每次传播门槛 0.002，不乘数值步长；0 关闭截断。生成的自抑制不受此门槛限制。":
    "Default threshold 0.002 per propagation, without solver-step scaling. Zero disables the cutoff. Locally generated inhibition is not filtered by this threshold.",
