  "留空不限。共同触达适应与传播巩固共享传播周期长度的时间窗预算，暂停和观察不补发；显式修改传播周期会重置本窗用量。":
    "Blank means unlimited. Co-contact and traversal updates share a time-window budget of one propagation interval. Pauses and observations do not refill it; explicitly changing the interval resets usage.",
