    "Optional controls are disabled by default. The first change to these mechanisms in an older model records a dynamics upgrade; previous checkpoints are preserved.",
  "查看机制、公式与版本规则": "Mechanisms, equations and version rules",
  "留空表示不限制；0 表示禁止相应操作。容量降低不会删除已有结构。这些参数改变模型演化，独立于显示性能档位。":
    "Blank means unlimited; 0 prevents the corresponding operation. Lower capacity does not delete existing structure. These parameters affect model evolution independently of display performance.",
  "查看预算、计数与版本规则": "Budgets, counters and version rules",
  "能量为可选实验资源，单位未经物理标定。供给来自显式外部端口；模型不会自动补充储备。初始储备只在出生时设置。":
    "Energy is an optional experimental resource without physically calibrated units. Supply comes from an explicit external port; reserves do not refill automatically. Initial reserves are set only at birth.",
  "查看能量、供给与饥饿规则": "Energy, supply and starvation rules",
  "可选。阶段时长之和须等于总运行时长；仅用于模拟环境或重放。":
    "Optional. Phase durations must sum to the run duration. Available for simulated environments or replay.",
  "创建后固定。": "Fixed after creation.",
  "无阶段时连续接受输入。创建后不可更改。":
    "Input is continuous when there are no phases. Fixed after creation.",
