    "Both category and source must be enabled for admission. Bypass applies only to this source's sensory frames.",
  调整来源策略: "Edit source policies",
  "策略变更会记录为配置版本。已排入内核的帧继续按其冻结的绕过标记递送；已接收但尚未排队的载体会重新检查来源开关。绕过竞争仍受外部增益、感官编码、实验阶段及模型资源约束。":
    "Policy changes are versioned. Frames already queued in the core retain their frozen bypass flags. Received but unqueued carriers are rechecked against source switches. Bypass still obeys external gain, sensory encoding, phases and model resource constraints.",
