    "Configure admission for external AI carriers here. AI providers and tools follow these policies; see the restoration checklist for delivery status. The model's own activity is not an external AI source.",
  "“允许准入”表示来源策略通过。实际递送还需要相应感官、设备权限和运行条件满足；关闭消息显示不会关闭输入。网络项只管感官刺激，设备读取及标量端口由各自权限管理。":
    "Admission permission only means the source policy passes. Delivery also requires sensory, device-permission and runtime conditions. Hiding messages does not disable input. Network policies apply to sensory stimuli; device read and scalar ports have separate permissions.",
