  "仅用于阈值滤波。": "Used only by the threshold filter.",
  视觉电平通道: "Visual level channels",
  视觉升降变化通道: "Visual rising/falling change channels",
  "首画面只建立变化基线；每个独立文件重新建立基线。":
    "The first frame establishes the change baseline only. Each independent file starts a new baseline.",
  视觉增益: "Visual gain",
  "单次图片／视频原件上限": "Original image/video size limit",
  视频时长上限: "Video duration limit",
  启用发声器: "Enable vocalizer",
  "被动记录匿名活动的振荡器控制值；页面试听须另行点击。":
    "Passively records oscillator controls for anonymous activity. Playback requires a separate click.",
  最大发声音数: "Maximum voices",
  发声激活下限: "Minimum vocalization activation",
  发声控制采样间隔: "Vocalization control sampling interval",
  发声频率下界: "Vocalization frequency lower bound",
