  截面采样间隔: "Section sampling interval",
  截面激活阈值: "Section activation threshold",
  结构候选最少节点: "Minimum structural candidate nodes",
  结构候选最多节点: "Maximum structural candidate nodes",
  "科学选择范围；先按激活/联想痕迹排序选取，完整保存选中子图。":
    "Scientific selection scope. Selects by activation/associative trace ordering and preserves the entire selected subgraph.",
