  实验助手: "Experiment assistant",
  "生成外部情境文本，经普通文本感官和输入总线递送。生成器只看到此处的情境描述，不读取意识内部状态。":
    "Generates external context text delivered through the ordinary text sensor and input bus. The generator sees only this context description, not the consciousness's internal state.",
