    "Observe how environmental stimuli affect connection formation, consolidation and forgetting.",
  新建发育训练: "New developmental training",
  "使用普通运行时持续塑造连接；训练过程保存在数据库，先天版本由你按恢复点登记。":
    "The standard Runtime continuously reshapes connections. Training is stored in the database; you register innate versions from checkpoints.",
