  "决定感官通道、执行器映射与躯体过滤身份；独立环境种子为空时，也用于环境随机化。创建后固定。":
    "Determines sensory channels, actuator mapping and body filter identity. Also randomizes the environment when no separate environment seed is set. Fixed after creation.",
  "留空沿用感官身份种子，保持旧行为。仅模拟物理与合成来源使用，其他来源保留该配置但不产生随机刺激。配对实验由区组种子列表管理，此处留空。":
    "Leave empty to use the sensory identity seed and preserve the previous behavior. Only simulated physical and synthetic sources use this value; other sources retain it without generating random stimuli. Paired experiments use their block seed list, so leave this empty there.",
  记录完整活动截面: "Record complete activity snapshots",
  "保存采样时的全部节点，包括弱活动、无触达痕迹及非候选节点。阈值与排序只用于另外的派生分析；完整记录会增加存储量。":
    "Save every sampled node, including weak activity, nodes without contact traces and non-candidates. Thresholds and ranking apply only to separate derived analyses. Complete recording uses more storage.",
  "输入编号只标明观察窗口的起点，不证明因果归属。候选、排序与外部注释不会改写原始活动或内核连接。":
    "Input identifiers anchor observation windows; they do not establish causation. Candidates, ranking and external annotations do not rewrite raw activity or Core connections.",
  "此记录未启用完整截面保存；可查看派生结果，不能据此还原全部活动。":
    "Complete snapshot recording was disabled. Derived results are available but cannot reconstruct all activity.",
  "这条历史记录未保存完整原始截面；派生结果不能代表全部节点活动。":
    "This historical record has no complete raw snapshot. Its derived results do not represent all node activity.",
  "本表默认包含已观察的全部节点统计。积分和聚合曲线来自离散采样，不是各节点的完整连续波形。":
    "This table includes statistics for all observed nodes by default. Integrals and aggregate curves come from discrete samples, not complete continuous waveforms for each node.",
